'use strict';
const C=ForestCore,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const KEY='forest-watch-v1';let state,filter='all',query='',selected=null,route=null,pickBase=false,photo='',toastTimer,storageOK=true;
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Kyiv',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const daysAgo=n=>{const d=new Date();d.setDate(d.getDate()-n);return d.toISOString().slice(0,10);};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel=s=>s?new Intl.DateTimeFormat('ru',{day:'numeric',month:'short'}).format(new Date(s+'T12:00:00')):'не проверялся';
function demo(){const make=(id,name,type,status,priority,lat,lng,ago,note,owner='')=>({id,name,type,status,priority,lat,lng,checkedAt:ago===null?'':daysAgo(ago),note,owner,due:'',photo:''});return {version:1,demo:true,base:{lat:50.537,lng:30.352},points:[
make('d1','Водоём у северной просеки','water','needs','high',50.565,30.369,24,'Учебный объект: проверить уровень воды и подъезд.','Лесной патруль'),
make('d2','Завал на лесной дороге','obstacle','problem','high',50.552,30.383,3,'Учебный объект: упавшие деревья перекрывают проезд.','Бригада № 2'),
make('d3','Пруд у старого карьера','water','problem','high',50.543,30.328,18,'Учебный объект: уровень воды снизился, нужен повторный осмотр.','Лесной патруль'),
make('d4','Сухие ветки у просеки','fuel','problem','medium',50.569,30.335,7,'Учебный объект: убрать растительные отходы с обочины.','Бригада № 1'),
make('d5','Водоём у южного въезда','water','verified','medium',50.531,30.376,2,'Учебный объект: вода есть, подъезд свободен.','Лесной патруль'),
make('d6','Восточный лесной проезд','obstacle','needs','medium',50.559,30.409,null,'Учебный объект: состояние проезда неизвестно.'),
make('d7','Западная точка забора','water','verified','low',50.552,30.309,5,'Учебный объект: площадка доступна.','Лесной патруль'),
make('d8','Расчищенная обочина','fuel','resolved','low',50.527,30.345,1,'Учебный объект: отходы убраны.','Бригада № 1')],log:[{text:'Загружены учебные данные. Они не описывают реальную территорию.',time:new Date().toISOString()}]};}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,5500);}
try{const raw=localStorage.getItem(KEY);state=raw?C.validate(JSON.parse(raw)):demo();if(!raw)localStorage.setItem(KEY,JSON.stringify(state));}catch(e){state=demo();storageOK=false;setTimeout(()=>toast('Не удалось прочитать журнал. Экспортируйте данные перед закрытием. '+e.message),500);}
function commit(next,message){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;storageOK=true;route=null;render();if(message)toast(message);return true;}catch{toast('Не удалось сохранить: память браузера недоступна или заполнена. Экспортируйте журнал и уменьшите фото.');return false;}}
function withLog(next,text){next.log=[{text,time:new Date().toISOString()},...next.log].slice(0,200);return next;}
const symbol=p=>p.type==='water'?'≈':p.type==='obstacle'?'!':'♧';
const pointClass=p=>p.status==='problem'?'problem':p.status==='needs'||C.stale(p)?'needs':'';
function badge(p){return `<span class="badge ${p.status==='problem'?'problem':p.status==='needs'?'needs':''}">${C.STATUS[p.status]}</span>`;}
const map=L.map('map',{zoomControl:true}).setView([50.549,30.36],13);
const grid=L.layerGroup().addTo(map),markers=L.layerGroup().addTo(map),routeLayer=L.layerGroup().addTo(map);
const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'});let tileFailures=0;
tiles.on('tileerror',()=>{tileFailures++;if(tileFailures===4)toast('Подложка недоступна. Точки и координатная сетка работают без неё.');});
if(navigator.onLine)tiles.addTo(map);
function drawGrid(){grid.clearLayers();const b=map.getBounds(),span=b.getNorth()-b.getSouth(),step=span>.4?.1:span>.08?.02:.005;let n=0;for(let lat=Math.ceil(b.getSouth()/step)*step;lat<b.getNorth()&&n<100;lat+=step,n++){L.polyline([[lat,b.getWest()],[lat,b.getEast()]],{color:'#8d9e88',weight:.6,opacity:.25,interactive:false}).addTo(grid);if(!map.hasLayer(tiles))L.marker([lat,b.getWest()+.001],{icon:L.divIcon({className:'grid-label',html:lat.toFixed(3)+'°',iconSize:[60,12]}),interactive:false}).addTo(grid);}n=0;for(let lng=Math.ceil(b.getWest()/step)*step;lng<b.getEast()&&n<100;lng+=step,n++)L.polyline([[b.getSouth(),lng],[b.getNorth(),lng]],{color:'#8d9e88',weight:.6,opacity:.25,interactive:false}).addTo(grid);}
map.on('moveend',drawGrid);drawGrid();
map.on('click',e=>{if(pickBase){pickBase=false;$('#pick-base').textContent='Изменить на карте';$('#map-hint').textContent='Нажмите на карту, чтобы добавить объект';commit(withLog({...state,base:{lat:e.latlng.lat,lng:e.latlng.lng}},'Изменена стартовая точка.'),'Стартовая точка обновлена');}else openEditor(null,e.latlng);});
function matches(p){return (!query||[p.name,p.owner,p.note].some(v=>v.toLowerCase().includes(query)))&&(filter==='all'||filter==='water'&&p.type==='water'||filter==='problem'&&p.status==='problem'||filter==='stale'&&C.stale(p));}
function focusPoint(id){selected=id;const p=state.points.find(p=>p.id===id);if(p){setView('map');map.setView([p.lat,p.lng],Math.max(map.getZoom(),14));renderList();openEditor(p);}}
function renderList(){const pts=state.points.filter(matches).sort((a,b)=>C.priority(b)-C.priority(a));$('#list-count').textContent=pts.length;$('#object-list').innerHTML=pts.length?pts.map(p=>`<button class="object-card ${selected===p.id?'selected':''}" data-point="${esc(p.id)}"><span class="type-symbol ${p.status==='problem'?'problem':''}">${symbol(p)}</span><span class="object-info"><strong>${esc(p.name)}</strong><span class="object-meta"><span>${esc(C.TYPES[p.type])}</span>${badge(p)}</span><span class="object-meta"><span>${p.checkedAt?'Проверка: '+dateLabel(p.checkedAt):'Ещё не проверялся'}</span><span>${p.priority==='high'?'↑ Высокий':''}</span></span></span></button>`).join(''):'<div class="empty">Объектов нет.<br>Добавьте точку на карте или измените фильтр.</div>';$$('[data-point]').forEach(b=>b.onclick=()=>focusPoint(b.dataset.point));}
function renderMap(){markers.clearLayers();const makeIcon=(html,cls='')=>L.divIcon({className:'marker-wrap',html:`<span class="map-marker ${cls}">${html}</span>`,iconSize:[30,30],iconAnchor:[15,15]});L.marker(state.base,{icon:makeIcon('⌂','base'),title:'Стартовая точка',alt:'Стартовая точка'}).addTo(markers).bindPopup('Старт и возврат плана обхода');state.points.filter(matches).forEach(p=>{const marker=L.marker([p.lat,p.lng],{icon:makeIcon(symbol(p),pointClass(p)),title:p.name,alt:p.name}).addTo(markers);const div=document.createElement('div');div.innerHTML=`<b>${esc(p.name)}</b><br>${badge(p)}<br>${esc(p.checkedAt?'Проверка: '+dateLabel(p.checkedAt):'Ещё не проверялся')}<br><button class="btn primary small popup-button">Открыть запись →</button>`;div.querySelector('button').onclick=()=>focusPoint(p.id);marker.bindPopup(div);});renderRoute();}
function renderRoute(){routeLayer.clearLayers();if(!route)return;const pts=route.stops.map(s=>state.points.find(p=>p.id===s.id));L.polyline([state.base,...pts,state.base],{color:'#225b45',weight:3,dashArray:'7 8',opacity:.8}).addTo(routeLayer);pts.forEach((p,i)=>L.marker(p,{interactive:false,icon:L.divIcon({className:'marker-wrap',html:`<span class="map-marker base">${i+1}</span>`,iconSize:[30,30],iconAnchor:[15,15]})}).addTo(routeLayer));}
function render(){const pts=state.points;$('#stat-total').textContent=pts.length;$('#stat-water').textContent=pts.filter(p=>p.type==='water').length;$('#stat-problem').textContent=pts.filter(p=>p.status==='problem').length;$('#stat-stale').textContent=pts.filter(p=>C.stale(p)).length;$('#task-count').textContent=pts.filter(p=>p.status==='problem').length;$('#demo-strip').hidden=!state.demo;$('#base-label').textContent=state.demo&&Math.abs(state.base.lat-50.537)<.00001?'Старт и возврат: учебная база':`Старт: ${state.base.lat.toFixed(4)}, ${state.base.lng.toFixed(4)}`;$('#route-result').hidden=!route;renderList();renderMap();renderTasks();renderLog();}
function renderTasks(){const pts=state.points.filter(p=>p.status==='problem'||p.status==='resolved').sort((a,b)=>(a.status==='resolved')-(b.status==='resolved')||C.priority(b)-C.priority(a));$('#tasks-list').innerHTML=pts.length?pts.map(p=>`<article class="task-card">${badge(p)}<h3>${esc(p.name)}</h3><p>${esc(p.note)||'Описание не добавлено.'}</p><p>Ответственный: <b>${esc(p.owner)||'не назначен'}</b><br>Срок: ${p.due?dateLabel(p.due):'не задан'}${p.due&&p.due<today()&&p.status==='problem'?' · <span style="color:var(--danger)">Просрочено</span>':''}</p><button class="btn" data-task="${esc(p.id)}">${p.status==='resolved'?'Посмотреть результат':'Открыть и обновить'} →</button></article>`).join(''):'<div class="empty">Открытых проблем пока нет. Создайте запись со статусом «Обнаружена проблема».</div>';$$('[data-task]').forEach(b=>b.onclick=()=>openEditor(state.points.find(p=>p.id===b.dataset.task)));}
function renderLog(){$('#log-list').innerHTML=state.log.length?state.log.map(e=>`<div class="log-entry"><time>${esc(new Intl.DateTimeFormat('ru',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Kyiv'}).format(new Date(e.time)))}</time><span>${esc(e.text)}</span></div>`).join(''):'<div class="empty">Здесь появятся добавления, проверки и изменения объектов.</div>';}
function setView(view){if(!['map','tasks','log'].includes(view))view='map';for(const v of ['map','tasks','log'])$('#'+v+'-view').hidden=v!==view;$$('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#view-name').textContent={map:'Полевая карта',tasks:'Задачи',log:'Журнал'}[view];$('#page-title').textContent={map:'Знать местность. Действовать вовремя.',tasks:'Проблема найдена. Что дальше?',log:'Каждая проверка оставляет след.'}[view];$('#page-subtitle').textContent={map:'Вода, доступ к ней и проблемы, которые важно проверить до пожара.',tasks:'Ответственные, сроки и результаты работ на территории.',log:'История изменений вашего полевого журнала.'}[view];if(location.hash!=='#'+view)history.replaceState(null,'','#'+view);if(view==='map')setTimeout(()=>map.invalidateSize(),30);}
$$('.nav').forEach(b=>b.onclick=()=>setView(b.dataset.view));window.addEventListener('hashchange',()=>setView(location.hash.slice(1)));
function setFilter(f){filter=f;$$('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===f));renderList();renderMap();}
$$('[data-filter]').forEach(b=>b.onclick=()=>setFilter(b.dataset.filter));$$('[data-stat]').forEach(b=>b.onclick=()=>{setView('map');setFilter(b.dataset.stat);});$('#search').oninput=e=>{query=e.target.value.trim().toLowerCase();renderList();renderMap();};
function fit(){map.invalidateSize();const pts=[state.base,...state.points];map.fitBounds(L.latLngBounds(pts.map(p=>[p.lat,p.lng])),{padding:[35,35],maxZoom:14});}$('#fit').onclick=fit;
$('#locate').onclick=()=>{if(!navigator.geolocation){toast('Геолокация не поддерживается. Выберите место на карте.');return;}navigator.geolocation.getCurrentPosition(pos=>{map.setView([pos.coords.latitude,pos.coords.longitude],15);toast('Ваше место показано. Нажмите на карту для новой записи.');},()=>toast('Не удалось получить местоположение. Разрешите геолокацию или выберите место на карте.'),{timeout:10000,maximumAge:30000});};
function openEditor(p=null,coords=null){$('#point-form').reset();$('#form-error').textContent='';$('#point-id').value=p?.id||'';$('#editor-title').textContent=p?'Карточка объекта':'Новый объект';const pos=coords||map.getCenter();for(const [field,key]of [['name','name'],['type','type'],['status','status'],['priority','priority'],['owner','owner'],['date','checkedAt'],['due','due'],['note','note']])$('#point-'+field).value=p?.[key]??({type:'water',status:'needs',priority:'medium'}[key]||'');$('#point-lat').value=(p?.lat??pos.lat).toFixed(6);$('#point-lng').value=(p?.lng??pos.lng).toFixed(6);$('#point-date').max=today();$('#delete-point').hidden=!p;photo=p?.photo||'';renderPhoto();$('#editor').showModal();}
function renderPhoto(){$('#photo-preview').replaceChildren();if(photo){const img=document.createElement('img');img.src=photo;img.alt='Фото объекта';$('#photo-preview').append(img);}$('#remove-photo').hidden=!photo;}
$('#remove-photo').onclick=()=>{photo='';$('#point-photo').value='';renderPhoto();};
$('#point-photo').onchange=async e=>{const file=e.target.files[0];if(!file)return;$('#save-point').disabled=true;$('#form-error').textContent='';try{if(!file.type.startsWith('image/')||file.size>15*1024*1024)throw Error('Выберите изображение до 15 МБ.');const url=URL.createObjectURL(file);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Не удалось прочитать изображение. Используйте JPEG, PNG или WebP.'));img.src=url;});const scale=Math.min(1,900/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const encoded=canvas.toDataURL('image/jpeg',.65);if(encoded.length>450000)throw Error('Фото слишком большое после сжатия. Выберите более простое изображение.');photo=encoded;renderPhoto();}finally{URL.revokeObjectURL(url);}}catch(err){$('#form-error').textContent=err.message;}finally{$('#save-point').disabled=false;}};
$('#point-status').onchange=e=>{if(['verified','problem','resolved'].includes(e.target.value)&&!$('#point-date').value)$('#point-date').value=today();};
$('#point-form').onsubmit=e=>{e.preventDefault();const id=$('#point-id').value||crypto.randomUUID();const p={id,name:$('#point-name').value.trim(),type:$('#point-type').value,status:$('#point-status').value,priority:$('#point-priority').value,lat:Number($('#point-lat').value),lng:Number($('#point-lng').value),owner:$('#point-owner').value.trim(),checkedAt:$('#point-date').value,due:$('#point-due').value,note:$('#point-note').value.trim(),photo};try{if(['verified','problem','resolved'].includes(p.status)&&!p.checkedAt)throw Error('Укажите дату фактической проверки.');if(p.checkedAt>today())throw Error('Дата проверки не может быть в будущем.');const exists=state.points.some(v=>v.id===id);const next=C.validate({...state,points:exists?state.points.map(v=>v.id===id?p:v):[...state.points,p]});if(commit(withLog(next,`${exists?'Обновлён':'Добавлен'} объект «${p.name}»: ${C.STATUS[p.status]}.`),'Запись сохранена на устройстве')){$('#editor').close();selected=id;}}catch(err){$('#form-error').textContent=err.message;}};
$('#delete-point').onclick=()=>{const p=state.points.find(v=>v.id===$('#point-id').value);if(p&&confirm(`Удалить объект «${p.name}»?`)){if(commit(withLog({...state,points:state.points.filter(v=>v.id!==p.id)},`Удалён объект «${p.name}».`),'Объект удалён'))$('#editor').close();}};
$$('.close-dialog').forEach(b=>b.onclick=()=>$('#editor').close());$('#add').onclick=()=>openEditor();$('#help').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=()=>$('#help-dialog').close();
$('#pick-base').onclick=()=>{setView('map');pickBase=!pickBase;$('#pick-base').textContent=pickBase?'Отменить выбор':'Изменить на карте';$('#map-hint').textContent=pickBase?'Выберите стартовую точку на карте':'Нажмите на карту, чтобы добавить объект';if(pickBase)toast('Нажмите на карту, чтобы задать старт и возврат.');};
$('#plan').onclick=()=>{try{const budget=Number($('#budget').value),speed=Number($('#speed').value);route=C.plan(state.points,state.base,budget,speed);const nearest=C.plan(state.points,state.base,budget,speed,'nearest');const panel=$('#route-result');panel.hidden=false;panel.innerHTML=route.stops.length?`<div class="route-summary"><b>${route.stops.length} проверок</b><span>≈ ${Math.ceil(route.minutes)} мин с возвратом</span><span>${route.km.toFixed(1)} км по прямой</span><span>${route.score} баллов приоритета</span></div><div class="route-list">${route.stops.map((s,i)=>{const p=state.points.find(p=>p.id===s.id);return `<button class="route-stop" data-stop="${esc(p.id)}"><b>${i+1}</b>${esc(p.name)} · ≈ ${Math.ceil(s.arrival)} мин</button>`;}).join('')}</div><div class="route-detail">При обходе ближайших точек: ${nearest.stops.length} проверок, ${nearest.score} баллов. Баллы — условная оценка важности проверок, не прогноз пожара. План учитывает все объекты журнала независимо от фильтра.<br>Пунктир — порядок посещения, а не доступный путь по дорогам. Время не учитывает рельеф и препятствия.</div>`:'<div class="empty">Подходящих точек в этом бюджете нет. Увеличьте время, измените старт или добавьте объекты, которым нужна проверка.</div>';$$('[data-stop]').forEach(b=>b.onclick=()=>focusPoint(b.dataset.stop));renderRoute();if(route.stops.length)map.fitBounds(L.latLngBounds([state.base,...route.stops.map(s=>state.points.find(p=>p.id===s.id))].map(p=>[p.lat,p.lng])),{padding:[40,40]});}catch(e){toast(e.message);}};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`forest-watch-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Журнал экспортирован вместе с фото. Сохраните файл как резервную копию.');};
$('#import-button').onclick=()=>$('#import').click();$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>8*1024*1024)throw Error('Файл слишком большой: максимум 8 МБ.');const next=C.validate(JSON.parse(await f.text()));if(confirm(`Заменить текущий журнал (${state.points.length} объектов) импортированным (${next.points.length})? Сначала экспортируйте текущий, если он нужен.`)){if(commit(withLog(next,'Импортирован журнал из файла.'),'Журнал импортирован'))fit();}}catch(err){toast('Импорт отменён: '+err.message);}finally{e.target.value='';}};
$('#clear-demo').onclick=()=>{if(confirm('Очистить текущий журнал и начать свой? Экспортируйте его, если хотите сохранить.')){if(commit({version:1,points:[],base:state.base,demo:false,log:[{text:'Создан личный журнал.',time:new Date().toISOString()}]},'Ваш журнал готов. Добавьте первый объект на карте.')){filter='all';setFilter('all');}}};
$('#load-demo').onclick=()=>{if(confirm('Заменить текущий журнал учебными данными? Экспортируйте текущий журнал, если он нужен.'))if(commit(demo(),'Учебные данные загружены')){query='';$('#search').value='';setFilter('all');fit();}};
function network(){const online=navigator.onLine;$('#connection').textContent=online?'● Онлайн':'○ Без сети';if(online&&!map.hasLayer(tiles)){tileFailures=0;tiles.addTo(map);}if(!online&&map.hasLayer(tiles))map.removeLayer(tiles);drawGrid();}window.addEventListener('online',network);window.addEventListener('offline',network);
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=C.validate(JSON.parse(e.newValue));route=null;render();toast('Журнал обновлён в другой вкладке.');}catch{toast('Не удалось прочитать изменения другой вкладки.');}}});
render();setView(location.hash.slice(1)||'map');network();fit();
if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').then(async reg=>{await navigator.serviceWorker.ready;if(!localStorage.getItem('forest-offline-notice')){toast('Готово к работе без сети. Подложка карты доступна только онлайн.');localStorage.setItem('forest-offline-notice','1');}}).catch(()=>toast('Автономная загрузка недоступна. Журнал сохранён, но не закрывайте страницу без сети.'));
